import boto3

def run_ocr(bucket_name, document_key):
    textract_client = boto3.client('textract')
    response = textract_client.detect_document_text(
        Document={
            'S3Object': {
                'Bucket': bucket_name,
                'Name': document_key
            }
        }
    )
    return response

from typing import Any, Dict

class S3Request:
    def __init__(self, bucket_name: str, object_key: str, operation: str):
        self.bucket_name = bucket_name
        self.object_key = object_key
        self.operation = operation

class S3Response:
    def __init__(self, status_code: int, data: Dict[str, Any]):
        self.status_code = status_code
        self.data = data

def normalize_response(response: Dict[str, Any]) -> Dict[str, Any]:
    normalized = {
        'status_code': response.get('ResponseMetadata', {}).get('HTTPStatusCode', 500),
        'data': response.get('Body', {}).get('string', '') if 'Body' in response else {}
    }
    return normalized

from boto3 import client

class StorageClient:
    def __init__(self, aws_access_key_id, aws_secret_access_key, region_name):
        self.client = client(
            's3',
            aws_access_key_id=aws_access_key_id,
            aws_secret_access_key=aws_secret_access_key,
            region_name=region_name
        )

    def get_client(self):
        return self.client

import boto3

def list_prefix(bucket_name, prefix):
    s3_client = boto3.client('s3')
    response = s3_client.list_objects_v2(Bucket=bucket_name, Prefix=prefix)
    if 'Contents' in response:
        return [obj['Key'] for obj in response['Contents']]
    else:
        return []

import boto3

def get_object_metadata(bucket_name, object_key):
    s3_client = boto3.client('s3')
    try:
        response = s3_client.head_object(Bucket=bucket_name, Key=object_key)
        return response
    except Exception as e:
        print(f"Error: {e}")
        return None

import boto3

def upload_to_s3(bucket_name, object_key, file_path):
    s3_client = boto3.client('s3')
    try:
        response = s3_client.upload_file(file_path, bucket_name, object_key)
        print(f'File uploaded successfully to {bucket_name}/{object_key}')
    except Exception as e:
        print(f'Error uploading file: {e}')

